{
  "segments": [
    {
      "name": "Owner-led course businesses",
      "buyer": "Course owner who controls marketing purchases",
      "market": "Independent businesses preparing another course launch",
      "problem": "Collecting learner testimonials before updating a sales page creates launch-linked urgency.",
      "access": "Public course pages may expose a business contact route without requiring an existing audience.",
      "tradeoff": "Purchasing authority is concentrated, but willingness to pay depends on launch frequency and remains unvalidated."
    },
    {
      "name": "Small SaaS marketing teams",
      "buyer": "Marketing lead with software budget authority",
      "market": "SaaS businesses updating landing pages or launching features",
      "problem": "Finding relevant customer proof for new messaging can delay campaign work.",
      "access": "Company websites provide research material, but the responsible buyer may be difficult to reach.",
      "tradeoff": "Recurring campaigns could support willingness to pay, but approval and existing tools may slow purchasing."
    },
    {
      "name": "Client-service marketing agencies",
      "buyer": "Agency owner responsible for client delivery tools",
      "market": "Agencies collecting testimonials for multiple clients",
      "problem": "Repeated client testimonial requests create coordination work.",
      "access": "Agency directories and public business websites can identify owners and contact routes.",
      "tradeoff": "Repeated delivery work could justify spending, but client permissions and unverified workflow fit increase adoption risk."
    }
  ],
  "firstBuyerWhy": {
    "advantage": "An owner-led course business combines a visible launch deadline with a potentially direct purchasing decision.",
    "risk": "Infrequent launches may make an existing free collection method sufficient.",
    "runnerUpWinsWhen": "Small SaaS marketing teams become preferable when an accessible budget owner has recurring proof-collection work."
  },
  "buyingMotion": "Sales-assisted",
  "paymentPath": {
    "offerKind": "Existing SaaS",
    "monetizationStatus": "Unknown",
    "pricingStatementIds": [],
    "verify": "Check Senja’s current official offer, paid capabilities, pricing and checkout before testing payment; s1 provides no pricing evidence.",
    "activation": "The prospect creates a customized Senja collection form and receives a genuine customer testimonial.",
    "adoption": "The prospect uses Senja again to collect additional testimonials for subsequent marketing work.",
    "paidConversion": "After verifying the actual offer, confirm payment for Senja through its supported purchase path; interest or form creation is not payment."
  },
  "firstExperiment": {
    "problem": "Course owners approaching a launch may lack a repeatable way to request learner testimonials.",
    "identifyProspects": "Research public course websites for a verified upcoming launch, an identifiable owner and a publicly provided business contact route; exclude prospects without relevant evidence.",
    "channel": "Direct email",
    "channelRationale": {
      "decision": "Researched outreach tests deadline-linked pain without assuming traffic, community membership or an installed user base.",
      "tradeoff": "Manual research limits reach but can expose workflow and purchasing objections faster than waiting for inbound discovery."
    },
    "firstAction": "Verify Senja’s current offer and prepare a personalized question using a documented public launch observation.",
    "activityTarget": {
      "quantity": 6,
      "activity": "Research eligible course owners and send a relevant individual email through a public business contact route."
    },
    "resources": {
      "assumedMinutes": 75,
      "preparationMinutes": 10,
      "researchMinutesPerActivity": 5,
      "executionMinutesPerActivity": 3,
      "responseMinutes": 10,
      "activityKind": "Researched contacts",
      "tools": [
        {
          "name": "Public course websites and search",
          "access": "Free/public"
        },
        {
          "name": "Free email account",
          "access": "Free/public"
        }
      ],
      "directSpend": 0,
      "constraints": "Assumes access to a free email account and browser; zero spend is an experiment assumption, and only relevant business contact routes are eligible."
    },
    "commercialLearning": "Determine whether launch-linked collection pain motivates a useful Senja event and, after offer verification, a concrete purchase decision.",
    "continueWhen": "An owner confirms an active collection problem and agrees to use Senja for a real learner request.",
    "adjustWhen": "Owners confirm the problem but identify an existing workaround or product-fit obstacle that prevents activation.",
    "stopWhen": "Stop this segment-channel test if eligible business contact routes cannot be found or conversations establish that the launch workflow does not require testimonial collection; silence alone is inconclusive.",
    "channelDescription": "Send individualized, permission-respecting emails to publicly reachable course owners, then offer a guided path into the existing SaaS rather than a paid service."
  },
  "alternatives": [
    {
      "channel": "Templates and communities",
      "comparison": {
        "benefit": "A useful testimonial-request template shared in a relevant course-owner community could support self-service discovery and activation.",
        "barrier": "Asset creation and community permission require effort, and neither audience access nor discovery traffic is established, so evidence may arrive slowly."
      },
      "preferWhen": "A relevant community explicitly permits useful resource sharing and its members already discuss testimonial collection.",
      "firstAction": "Check public community rules and discussions before creating a Senja-oriented collection template."
    },
    {
      "channel": "Ecosystem and user signals",
      "comparison": {
        "benefit": "An accessible ecosystem listing or permissioned existing-user workflow could reveal higher-intent prospects with less cold-contact research.",
        "barrier": "Listings require fit and approval, while user-behaviour analysis requires authorized data access; neither is established, making evidence speed uncertain."
      },
      "preferWhen": "A relevant ecosystem offers a free accessible entry point or authorized user data reveals repeated collection activity.",
      "firstAction": "Check public ecosystem participation requirements and establish whether permissioned existing-user evidence is available."
    }
  ],
  "messages": [
    {
      "subject": "Collecting learner testimonials",
      "body": "Hi [name], I noticed [verified public observation to research]. How are you collecting learner testimonials for your next launch? I’m exploring whether Senja’s customizable collection forms fit that workflow. Is this currently a priority?"
    },
    {
      "subject": "Worth sharing a collection workflow?",
      "body": "Hi [name], would it be useful if I shared a short example of collecting learner testimonials with Senja? If you already have a reliable process or this is not timely, I’m happy to leave it there."
    }
  ],
  "positioning": "Position Senja as a customizable testimonial-collection tool for course owners preparing launch proof, without repeating the owner’s unverified claim of twice as many testimonials.",
  "unknowns": [
    "Current Senja pricing, paid capabilities and checkout have not been verified.",
    "Course-owner urgency, purchasing authority and willingness to pay are hypotheses, not market findings.",
    "Founder email access, existing users, audience, relationships and available product access are unknown resources rather than established assets relevant to this experiment; only the listed free tools are assumed for the "
  ],
  "recommendationBasis": {
    "segments": [
      "s1"
    ],
    "acquisitionChannels": [
      "s1"
    ],
    "outreachTemplates": [
      "s1"
    ],
    "firstTenPlaybook": [
      "s1"
    ],
    "thirtyDayPlan": [
      "s1"
    ]
  },
  "contractVersion": "2"
}

